def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--operation',choices=['revenuecat_emulator_tests'],required=True)
    parser.add_argument('--verify-only',action='store_true',help='Validate embedded input bytes without writes or execution')
    args=parser.parse_args()
    payload=base64.b64decode(''.join(PAYLOAD.split()),validate=True)
    if hashlib.sha256(payload).hexdigest()!=PAYLOAD_SHA256:
        raise ValueError('Embedded ZIP digest mismatch')
    content={}
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        entries=archive.infolist()
        if len(entries)!=len(MEMBERS) or {x.filename for x in entries}!=set(MEMBERS):
            raise ValueError('Embedded member set mismatch')
        for info in entries:
            path=PurePosixPath(info.filename)
            if path.is_absolute() or path.parts[0]!='operations' or '..' in path.parts or '\\' in info.filename:
                raise ValueError('Unsafe archive member')
            if (info.external_attr>>16)&0o170000!=0o100000 or info.file_size>2_000_000:
                raise ValueError('Unsupported archive entry type/size')
            data=archive.read(info)
            expected=MEMBERS[info.filename]
            if len(data)!=expected['bytes'] or hashlib.sha256(data).hexdigest()!=expected['sha256']:
                raise ValueError('Embedded file digest mismatch')
            content[info.filename]=data
    if args.verify_only:
        print(json.dumps({'transport_verification':'PASS','files':len(content),'execution_performed':False}))
        return 0
    root=Path(__file__).resolve().parent
    # Validate every destination before writing any; never replace existing content.
    for name,data in content.items():
        target=root/name
        for parent in [target,*target.parents]:
            if parent==root.parent:
                break
            if parent.is_symlink():
                raise ValueError('Symlink in extraction destination')
        if target.exists() and (not target.is_file() or target.read_bytes()!=data):
            raise ValueError('Existing workload file differs: '+name)
    for name,data in sorted(content.items()):
        target=root/name
        target.parent.mkdir(parents=True,exist_ok=True)
        if not target.exists():
            with target.open('xb') as stream:
                stream.write(data)
    command=['python3','operations/run_workload.py','--operation','revenuecat_emulator_tests']
    print('GM_TRANSPORT '+json.dumps({'schema':'gatemigrate.workload-transport.v1',
        'bootstrap_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        'payload_sha256':PAYLOAD_SHA256,'input_manifest_sha256':MANIFEST_SHA256,
        'command':command,'files':len(content)}),flush=True)
    return subprocess.run(command,cwd=root,check=False).returncode

if __name__=='__main__':
    sys.exit(main())
